import{_ as t,o,c as i,a2 as a}from"./chunks/framework.BTLSZHNB.js";const m=JSON.parse('{"title":"0011 — Resource identity: UID, generation, and revision","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0011-resource-identity-generation-and-revision.md","filePath":"spec/decisions/0011-resource-identity-generation-and-revision.md"}'),n={name:"spec/decisions/0011-resource-identity-generation-and-revision.md"};function s(d,e,r,c,l,u){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="_0011-—-resource-identity-uid-generation-and-revision" tabindex="-1">0011 — Resource identity: UID, generation, and revision <a class="header-anchor" href="#_0011-—-resource-identity-uid-generation-and-revision" aria-label="Permalink to &quot;0011 — Resource identity: UID, generation, and revision&quot;">​</a></h1><ul><li>Status: accepted</li><li>Date: 2026-08-06</li><li>Owners: Takoform maintainers</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The v1alpha2 wire duplicates naming and versioning concerns: <code>metadata.name</code>, <code>spec.name</code>, a provider <code>name</code> attribute, <code>output.name</code>, <code>observed.id</code>, and <code>output.id</code> coexist; <code>resourceVersion</code> acts both as the desired-state generation and as the strong ETag for the whole representation, even though observe/refresh legitimately change status without changing desired state. Form Definitions also each re-declare envelope facts (<code>observed.ready</code>, <code>observed.generation</code>, <code>output.id</code>, portability markers) that belong to the protocol, not to any one Form. Finally, provider state keys resources by <code>packageDigest</code> in addition to FormRef, so the same resource read through a different — equally valid — package of the same Form becomes unaddressable.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The v1alpha3 resource envelope owns identity and versioning; Form schemas own only portable desired fields.</p><ul><li><code>metadata.name</code> is the only name. <code>spec.name</code> and per-Form envelope fields (<code>/name</code>, <code>observed.id</code>, <code>observed.generation</code>, <code>observed.ready</code>, <code>output.id</code>, <code>output.name</code>, and similar) are removed from Form Definitions.</li><li><code>metadata.uid</code> is a host-issued immutable identity. Deleting and recreating a same-named resource yields a different UID. Mutations may carry an expected UID and are rejected on mismatch.</li><li><code>metadata.generation</code> (canonical decimal string) increments only when the portable desired spec changes.</li><li><code>metadata.revision</code> (canonical decimal string) increments whenever the full representation — including status and outputs — changes. The HTTP strong ETag is the quoted revision.</li><li><code>status.observedGeneration</code> states which desired generation the status reflects. <code>status.conditions</code> uses the closed set <code>Ready</code>, <code>Reconciling</code>, <code>Degraded</code>, <code>Drifted</code>, <code>Blocked</code>, <code>Deleting</code> with closed portable reasons; host-internal codes go to a separate <code>hostReason</code>.</li><li>Desired-state mutations fence on the expected generation; representation fences use <code>If-Match</code> on the revision. Stale fences fail with <code>generation_conflict</code> (412) or <code>revision_conflict</code> (412).</li><li>The Form semantic identity of a resource is its exact FormRef. The package digest used at creation may be recorded as audit evidence but never enters resource identity, queries, or update/delete fences. A host that installed the same FormRef from a different legitimate package must read and delete the same resource.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Provider v2.1 family-resource state identity is <code>space</code>, <code>apiVersion</code>, <code>kind</code>, <code>uid</code>; a JSON-serialized <code>status.outputs</code> document (<code>outputs_json</code>) replaces the string-map outputs; the ETag/generation split removes the global client-side mutation mutex.</li><li>Conformance gains UID-stability, delete/recreate UID change, generation-only-on-spec-change, revision-on-status-change, stale-fence rejection, and package-digest-substitution checks.</li><li>Form authoring gets simpler: definitions stop repeating envelope plumbing.</li></ul><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Keep one <code>resourceVersion</code> for both fences.</strong> Rejected because observe/refresh then either lies (status changes invisible to ETag) or breaks desired-state fencing (every observe invalidates client fences).</li><li><strong>Key state by <code>space/name</code> only.</strong> Rejected because delete/recreate would silently rebind old state to a new resource; UID makes that visible.</li><li><strong>Keep <code>packageDigest</code> in identity for provenance.</strong> Rejected because provenance is evidence, not identity; it is retained as an audit field.</li></ul>',11)])])}const g=t(n,[["render",s]]);export{m as __pageData,g as default};
